441	\section{Canonical parameters of the Pauli basis test}
442	% Paper label sec:qld-complexity kept for cross-reference fidelity (the complexity
443	% statements of that subsection are outside the scope of this development).
444	\label{sec:qld-complexity}
445	
446	We specify a canonical setting of the parameter tuple $\mathsf{qldparams}$ as a function of an integer $R$, and bound the resulting soundness function. All logarithms are base $2$.
447	
448	\begin{definition}[Canonical parameters of the Pauli basis test]\label{def:introparams}
449		\uses{thm:pauli}
450		Let $a, b$ be the universal constants of Theorem~\ref{thm:pauli}, and let $c$ be the smallest \emph{even} integer that is at least $(b+a)/b$. For every integer $R \ge 4$, define the tuple $\mathsf{introparams}(R) = (q, m, d)$ by
451		\begin{itemize}
452			\item $q = 2^k$ for $k = c \lceil \log \log R \rceil + 1$,
453			\item $m = 2^j$, where $j$ is the unique integer with $2^j \le c \lceil \log R \rceil + 1 < 2^{j+1}$,
454			\item $d = 1$.
455		\end{itemize}
456		The letter $k$ here denotes the exponent of the field size and is unrelated to the simultaneity parameter $k$ of the classical game. With this choice the Pauli basis test certifies the presence of an $M = 2^m$-qudit maximally entangled state of local dimension $q$, equivalently an $(M \log q)$-qubit EPR state, and the choice $d = 1$ runs the low individual degree test multilinearly.
457	\end{definition}
458	
459	\begin{lemma}[Soundness bound for the canonical parameters]\label{lem:delta-bound}
460		\uses{def:introparams, def:admissible, thm:pauli}
461		For all integers $R \ge 4$, the parameter tuple $\mathsf{introparams}(R) = (q,m,d)$ is admissible (Definition~\ref{def:admissible}) and satisfies $2^m \ge R$. Furthermore, there exist universal constants $a' \ge 1$ and $0 < b' \le 1$ such that the function $\delta_{\mathrm{qld}}(\eps, m, d, q)$ of Theorem~\ref{thm:pauli} is at most
462		\[
463			a' \bigl( (\log R)^{a'} \cdot \eps^{b'} + (\log R)^{-b'} \bigr)\;.
464		\]
465	\end{lemma}
466	\begin{proof}
467		\uses{def:introparams, def:admissible, def:admissible-size, thm:pauli}
468		Since $c$ is even, the exponent $k = c \lceil \log\log R \rceil + 1$ is odd, so $q = 2^k$ is an admissible field size; $m$ divides $q$ because $2^j \le c \lceil \log R \rceil + 1 \le 2 \log^c R \le 2^k$, so $j \le k$ and both are powers of $2$; and $d = 1 \ge 1$. Hence the tuple is admissible. Since $m = 2^j \ge (c/2) \log R$, we get $2^m \ge R^{c/2} \ge R$, using $c \ge 2$.
469	
470		For the soundness bound, write $\delta_{\mathrm{qld}}(\eps,m,d,q) = a(md)^a \eps^b + a(md)^a q^{-b} + a(md)^a 2^{-bmd}$ and use $d = 1$, $m \le 2c \log R$, and $q = 2^k \ge \log^c R$. The first term is at most $a(2c)^a (\log R)^a \eps^b$. The second term is at most $a(2c)^a (\log R)^{a - cb} \le a(2c)^a (\log R)^{-b}$, since $cb - a \ge b$ by the choice of $c$. For the third term, $m \ge (c/2) \log R \ge \log R$ gives $2^{-bm} \le R^{-b}$, so
471		\[
472			a(md)^a\, 2^{-bm}
473			\le a(2c)^a (\log R)^a R^{-b}
474			= a(2c)^a \bigl( (\log R)^{a+b} R^{-b} \bigr) (\log R)^{-b}
475			\le a(2c)^a\, C\, (\log R)^{-b}\;,
476		\]
477		where $C = \sup_{R' \ge 4} (\log R')^{a+b} (R')^{-b}$ is finite --- the function is continuous in $R'$ and tends to $0$ as $R' \to \infty$ --- and depends only on the universal constants $a$ and $b$. Summing the three bounds, the statement follows with $a' = a(2c)^a (1 + C)$ and $b' = b$.
478	\end{proof}
479	
480	\begin{remark}[A comparison of exponents in the source proof of Lemma~\ref{lem:delta-bound}]\label{rem:delta-bound-exponent-comparison}
481		The source proof bounds the third term of $\delta_{\mathrm{qld}}$ by asserting $2^{-bmd} \le q^{-b}$ ``because $k \le m$'', comparing the field exponent $k = c \lceil \log\log R \rceil + 1$ with $m = 2^j$. The inequality $k \le m$ does not follow from Definition~\ref{def:introparams}: if the universal constants of Theorem~\ref{thm:pauli} were $a = 1$ and $b = 1/2$, then $c = 4$, and $R = 5$ gives $k = 9$ and $m = 8$. The proof above instead bounds $2^{-bm} \le R^{-b}$ directly from $m \ge (c/2) \log R \ge \log R$, which yields the same conclusion after enlarging the universal constant $a'$.
482	\end{remark}

118	Quantum soundness of a version of the classical low-degree test for polynomials of low \emph{total} degree was claimed by Natarajan and Vidick, building on an analysis of a three-prover version of the test by Vidick; there is a known gap in the soundness analysis of that test, and it is not used here. Instead, the construction relies on the low \emph{individual} degree test, whose quantum soundness is proved in~\cite{Ji2020LowIndividualDegree} and generalized in~\cite{Ji2021Quantum}. The statement below is the form most directly useful in what follows.
119	
120	% The paper states this result in a theorem environment with the label lem:ld-soundness.
121	% We keep both the environment and the label verbatim for cross-reference fidelity.
122	\begin{theorem}[Quantum soundness of the simultaneous classical low individual degree test]\label{lem:ld-soundness}
123		\uses{def:ld-game, def:ld-question-distribution, def:ld-win-predicate, def:ld-meas, def:projective-strategy-general, def:tensor-product-value, def:povm-distance, def:bracket}
124		There exists a function
125		\[
126			\delta_{\mathrm{ld}}(\eps, q, m, d, k) = a\,(dmk)^a \bigl(\eps^b + q^{-b} + 2^{-bmd}\bigr)
127		\]
128		for universal constants $a \ge 1$ and $0 < b \le 1$ such that the following holds. For all $\eps > 0$ and every parameter tuple $\mathsf{ldparams} = (q,m,d,k)$ as in Definition~\ref{def:ld-game} (so $m, d, k \ge 1$, $q$ is an admissible field size, and $m$ divides $q$), and for all projective strategies $(\psi, A, B)$ that succeed with probability at least $1-\eps$ in the game $\mathfrak{G}^{\mathrm{ld}}_{\mathsf{ldparams}}$, there exist measurements
129		\[
130			G^w \in \mathrm{PolyMeas}(m,q,d,k)
131		\]
132		on $\hilb_w$ for $w \in \{\mathrm A,\mathrm B\}$, where by slight abuse of notation $m$, $q$, $d$ denote the constant tuples $(m,\ldots,m)$, $(q,\ldots,q)$, $(d,\ldots,d)$ of length $k$, such that
133		\begin{align*}
134			A^{\mathsf{Point},\, u}_{a_1,\ldots,a_k} \ot I_{\mathrm B}
135			&\approx_{\delta_{\mathrm{ld}}}
136			I_{\mathrm A} \ot G^{\mathrm B}_{[(g_1(u),\ldots,g_k(u)) = (a_1,\ldots,a_k)]}\;,\\
137			G^{\mathrm A}_{[(g_1(u),\ldots,g_k(u)) = (a_1,\ldots,a_k)]} \ot I_{\mathrm B}
138			&\approx_{\delta_{\mathrm{ld}}}
139			I_{\mathrm A} \ot B^{\mathsf{Point},\, u}_{a_1,\ldots,a_k}\;,\\
140			G^{\mathrm A}_{g_1,\ldots,g_k} \ot I_{\mathrm B}
141			&\approx_{\delta_{\mathrm{ld}}}
142			I_{\mathrm A} \ot G^{\mathrm B}_{g_1,\ldots,g_k}\;,
143		\end{align*}
144		where $\delta_{\mathrm{ld}} = \delta_{\mathrm{ld}}(\eps,q,m,d,k)$, all three approximations are with respect to the state $\ket{\psi}$, and the bracket notation for post-processed outcomes is that of Definition~\ref{def:bracket}. The first two approximations hold on average over the uniform distribution on $u \in \F_q^m$; no question distribution is associated with the third.
145	\end{theorem}
146	\begin{proof}
147		\uses{def:ld-question-distribution, def:ld-win-predicate, def:ld-meas, def:povm-distance}
148		Let $\Sigma = \F_q$ and let $\code \subseteq \Sigma^q$ be the Reed--Solomon code of degree $d$: the set of all $(p(x_1),\ldots,p(x_q))$ where $p\colon \F_q \to \F_q$ is a univariate polynomial of degree at most $d$ and $x_1,\ldots,x_q$ enumerate $\F_q$. We may assume $d < q$. In the opposite regime the statement is immediate: for $d \ge q$ the prefactor gives $\delta_{\mathrm{ld}} \ge a\,(dmk)^a\, q^{-b} \ge q^{a-b} \ge 1$, using $m, k \ge 1$, while the quantity bounded in Definition~\ref{def:povm-distance} never exceeds $2$ for families of POVM elements, so the three approximations hold for an arbitrary choice of $G^w \in \mathrm{PolyMeas}(m,q,d,k)$. For $d < q$, evaluation is injective on polynomials of degree at most $d$ and a nonzero polynomial of degree at most $d$ vanishes at no more than $d$ of the $q$ points, so $\code$ is a linear $[q,\, d+1,\, q-d]_\Sigma$ code.
