 skip        = ["command.tex", "template.tex"]

 # The source-key registry. A note is named `<key>_<topic>.tex` (or, in the
 # hyphenated house style here, `<key>-<topic>.tex`), and the shared tool
 # resolves the key by longest registered prefix followed by a separator.
 # Nearly every note audits the one source paper of this project,
 # arXiv:2009.12982 (quantum soundness of the classical low individual degree
 # test): under `issue` for the issue-anchored stems, `naimark` for the
 # Naimark-dilation note, and `truncation-combinatorics` for the
